import math

def otherside_rightangle(w, h):
    # Check if the inputs are already the legs (return hypotenuse)
    if w**2 + h**2 > max(w, h)**2:
        return math.sqrt(w**2 + h**2)
    else:
        # Assume one is the hypotenuse and the other is a leg
        # Determine which one is larger to handle either case
        if w > h:
            return math.sqrt(w**2 - h**2)
        else:
            return math.sqrt(h**2 - w**2)
