def left_rotate(n, d):
    # Handle the case where d is 0 (no rotation)
    if d == 0:
        return n
    # Handle the case where d is greater than 32 bits (modulo 32)
    d = d % 32
    # Perform the left rotation
    return ((n << d) & 0xFFFFFFFF) | ((n >> (32 - d)) & 0xFFFFFFFF)
